        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, duration/1e6 AS ms, time FROM abnormal_traces WHERE trace_id='2dfd79492118de102bf42abb4022a46d' ORDER BY time", "claim": "In one trace, getAllContacts takes about 1,658 ms but its outbound GET to ts-contacts-service starts about 1.65 s later and takes about 6 ms."},
        {"kind": "metric", "sql": "SELECT metric, AVG(value) avg_v, MAX(value) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-admin-basic-info-service%' AND metric IN ('k8s.pod.cpu.usage','container.memory.working_set','k8s.container.restarts') GROUP BY metric", "claim": "Admin-basic-info pod CPU, memory and restarts stay low and flat, so the delay is not resource saturation."}
      ]
    }
  ],
  "propagation": [
